def merge_sort(a)
  return a.sort if a.size < 1024            # base case (leaf)
  mid = a.size / 2
  left  = Ractor.new(a[0...mid]) { |part| merge_sort(part) }
  right = Ractor.new(a[mid..])   { |part| merge_sort(part) }
  merge(left.take, right.take)              # join + combine
end
